fn factory(job: &mut Job, event: &Event, dials: &Dials) -> Option<Vec<Effect>> {
    let runs = job.stage.kind() == Kind::Factory;
    Some(match (job.stage, event) {
        (Stage::Ship, Event::PrOpened { url }) => {
            job.pr = Some(url.clone());
            advance(job, dials)
        }
