//! N11 (PLAN.md D26): can the stack's `configuration` worker carry Bastion's
//! harness and factory defaults? `ensure` seeds an id once and `get` reads it.
//! `cargo run -p bastion-spikes --example n11_config -- ensure|get`.

use bastion_spikes::{call_default, connect};
use serde_json::json;

const ID: &str = "spike-d26";

#[tokio::main]
async fn main() {
    let iii = connect("spike-n11");
    let step = std::env::args().nth(1).unwrap_or_else(|| "get".into());
    let answer = match step.as_str() {
        "ensure" => {
            let payload = json!({
                "id": ID,
                "name": "Spike D26",
                "description": "A seeded default the owner may edit.",
                "schema": { "type": "object" },
                "initial_value": { "rules": ["seeded"] },
            });
            call_default(&iii, "configuration::ensure", payload, 10_000).await
        }
        _ => call_default(&iii, "configuration::get", json!({ "id": ID }), 10_000).await,
    };
    println!("{step}: {answer:?}");
    std::process::exit(0);
}
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct Quit {
    stop_stack: bool,
}

#[component]
pub fn App() -> impl IntoView {
    let (route, set_route) = signal(Route::Jobs);
    provide_context::<Nav>(set_route);
    let (profile, set_profile) = signal(String::new());
    let (asking, set_asking) = signal(false);
    spawn_local(async move {
        if let Ok(p) = ipc::call::<ActiveProfile, String>(command::PROFILE, None {}).await {
            set_profile.set(p.name);
        }
    });
    ipc::listen(event::QUIT_REQUESTED, move |()| set_asking.set(true));
    let quit = move |stop_stack: bool| {
        spawn_local(async move {
            let _ = ipc::call::<(), String>(command::QUIT, Quit { stop_stack }).await;
        });
    };

    view! {
        <a href="#main" class="sr-only focus:not-sr-only focus:absolute focus:m-2 focus:rounded focus:bg-primary focus:px-3 focus:py-2 focus:text-white">
            "Skip to content"
        </a>
        <div class="grid min-h-screen grid-cols-[200px_minmax(0,1fr)]">
            <nav aria-label="Main" class="sticky top-0 flex h-screen flex-col gap-1 border-r border-line bg-panel p-3">
                <p class="m-0 mb-3 px-2 text-lg font-extrabold">"Bastion"</p>
                {PAGES.map(|(target, label, glyph)| {
                    let here = target.clone();
                    view! {
                        <button
                            class="flex items-center gap-2 rounded-lg px-2 py-1.5 text-left hover:bg-line aria-[current=page]:bg-primary aria-[current=page]:text-white"
                            aria-current=move || (section(&route.get()) == here).then_some("page")
                            on:click=move |_| set_route.set(target.clone())
                        >{icons::icon(glyph)}{label}</button>
                    }
                })}

